def _inh(label, url, design="diretriz, consenso ou ensaio primário identificado no título"):
    return {"label": label, "url": url, "design": design, "verifiedAt": INHERITED, "scope": _INH_SCOPE}

def _pm(label, pmid, design):
    return {"label": label, "url": f"https://pubmed.ncbi.nlm.nih.gov/{pmid}/", "design": design, "verifiedAt": CHECKED, "scope": _PM_SCOPE}

